package service
import("context";"errors";"path/filepath";"testing";"time";"task133-structload/internal/clock";"task133-structload/internal/model";"task133-structload/internal/store")
func TestBug27_ComponentCannotCrossProjectLevelBoundary(t *testing.T){st,e:=store.Open(filepath.Join(t.TempDir(),"x.db"));if e!=nil{t.Fatal(e)};defer st.Close();svc:=New(st,clock.NewFake(time.UnixMilli(1740000000000)));ctx:=context.Background();p1,_:=svc.CreateProject(ctx,CreateProjectInput{Code:"P1",Name:"one",Exposure:"C",Importance:"II",WindSpeed:380});p2,_:=svc.CreateProject(ctx,CreateProjectInput{Code:"P2",Name:"two",Exposure:"C",Importance:"II",WindSpeed:380});l2,_:=svc.CreateLevel(ctx,p2.ID,CreateLevelInput{Name:"L2",GrossArea:100});in:=CreateComponentInput{LevelID:l2.ID,Code:"BAD",Type:"beam",Span:4000,TributaryArea:100,TributaryWidth:100,KLL:1,PhiB:90,PhiC:90,PhiV:90,WindSurface:"none"};if _,e=svc.CreateComponent(ctx,p1.ID,in);!errors.Is(e,model.ErrNotFound){t.Fatalf("service error=%v",e)};bad:=model.Component{ID:"bad",ProjectID:p1.ID,LevelID:l2.ID,Code:"BAD",Type:model.ComponentBeam,Span:4000,KLL:1,WindSurface:model.WindNone};if e=st.CreateComponent(ctx,bad);!errors.Is(e,model.ErrInvariant){t.Fatalf("store error=%v",e)}}
